import{_ as e,c as n,o as a,ae as s}from"./chunks/framework.Bi6zybwU.js";const p=JSON.parse('{"title":"Language Settings","description":"Language Settings","frontmatter":{"title":"Language Settings","description":"Language Settings"},"headers":[],"relativePath":"guide/table-settings/language-settings.md","filePath":"guide/table-settings/language-settings.md"}'),g={name:"guide/table-settings/language-settings.md"};function o(i,t,l,r,u,h){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="language-settings" tabindex="-1">Language Settings <a class="header-anchor" href="#language-settings" aria-label="Permalink to &quot;Language Settings&quot;">​</a></h1><p>The <strong>Language Settings</strong> in Ninja Tables lets you select any language for your tables according to your needs. Follow this easy guide to set up the language settings in your table.</p><ul><li>The first step is to go to the <strong>Table Configuration</strong> tab, where you will find the <strong>Language</strong> <strong>Settings</strong> on the left side.</li><li>After clicking on this option, you can configure your preferred language for three settings.Such as- <strong>Empty Results Text</strong>, <strong>Search Box Placeholder Text</strong>, and <strong>Search Dropdown Heading.</strong><img src="https://ninjatables.com/wp-content/uploads/2023/01/language-settings-1-1024x437.png" alt="language settings in ninja tables"></li><li>The title of these options already explains the functions, you can place the language you want and then click on the <strong>Update Configuration</strong> to save the settings.</li><li>In the final step, you just have to preview the output to see the results of your table. In the table given below, words are set to <strong>Albanian</strong> in the search placeholder when the table rows are empty &amp; in the dropdown heading. <img src="https://ninjatables.com/wp-content/uploads/2023/01/language-settings-3.png" alt="language in tables"><img src="https://ninjatables.com/wp-content/uploads/2023/01/language-settings-4.png" alt="language in data table"> This quick guide explains to you how to use** Language Settings** in your table easily.</li></ul>',3)])])}const d=e(g,[["render",o]]);export{p as __pageData,d as default};
